import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_02_latency_chain.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_03_context_compaction.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_04_migration_map.png",b=JSON.parse('{"title":"模型不背锅：Codex 选型、提速与迁移的系统方法","description":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。","frontmatter":{"title":"模型不背锅：Codex 选型、提速与迁移的系统方法","description":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。","date":"2026-08-10","topic":"AI 底层学习","section":"Codex · 官方文档十讲","readingTime":6,"source":"2026-08-10/ai_codex_06_model_speed_delivery.md","status":"published","cover":"/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-06-model-speed-delivery"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模型不背锅：Codex 选型、提速与迁移的系统方法"}],["meta",{"property":"og:description","content":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-06-model-speed-delivery"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"模型不背锅：Codex 选型、提速与迁移的系统方法"}],["meta",{"name":"twitter:description","content":"AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_06_01_model_matrix.png"}]],"prev":{"text":"从单兵助手到可验证流水线：Worktree、Git、codex exec、CI 与跨平台开发","link":"/ai/ai-codex-05-engineering-automation"},"next":{"text":"Codex 用久了才懂：速查、排障与最佳实践的系统方法","link":"/ai/ai-codex-07-practice-governance"}},"headers":[],"relativePath":"ai/ai-codex-06-model-speed-delivery.md","filePath":"ai/ai-codex-06-model-speed-delivery.md","lastUpdated":null}'),c={name:"ai/ai-codex-06-model-speed-delivery.md"};function h(s,e,p,_,m,x){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="模型不背锅-codex-选型、提速与迁移的系统方法" tabindex="-1">模型不背锅：Codex 选型、提速与迁移的系统方法 <a class="header-anchor" href="#模型不背锅-codex-选型、提速与迁移的系统方法" aria-label="Permalink to &quot;模型不背锅：Codex 选型、提速与迁移的系统方法&quot;">​</a></h1><p>AI 编程任务变慢或失败时，人们最容易先换模型。可真正决定交付质量的，往往是上下文是否失控、任务是否混杂、工具链能否验证、环境能否重建。模型当然重要，但它只是系统中的推理引擎，不是替所有工程问题背锅的万能旋钮。</p><p>本文以教程第 30～32 篇为线索，对照 OpenAI Docs 的 Models、Best practices 与 Import 章节，讨论模型选择、速度与上下文，以及从其他编码代理迁移。Windows 环境归入第五篇，完整项目交付归入第三篇；文中不固化易变的型号、价格和配额，而是提供能够跨版本使用的决策方法。</p><h2 id="一、选模型之前先给任务分类" tabindex="-1">一、选模型之前先给任务分类 <a class="header-anchor" href="#一、选模型之前先给任务分类" aria-label="Permalink to &quot;一、选模型之前先给任务分类&quot;">​</a></h2><h3 id="_1-1-复杂度决定需要多少推理" tabindex="-1">1.1 复杂度决定需要多少推理 <a class="header-anchor" href="#_1-1-复杂度决定需要多少推理" aria-label="Permalink to &quot;1.1 复杂度决定需要多少推理&quot;">​</a></h3><p>查找符号、修改文案和机械迁移通常不需要最高推理预算；跨模块设计、并发缺陷和陌生代码库诊断，则需要更强的规划与长链推理。让所有任务都使用同一档模型，会在成本、速度或质量上浪费一端。</p><h3 id="_1-2-风险决定需要多少审查" tabindex="-1">1.2 风险决定需要多少审查 <a class="header-anchor" href="#_1-2-风险决定需要多少审查" aria-label="Permalink to &quot;1.2 风险决定需要多少审查&quot;">​</a></h3><p>即使任务本身简单，只要涉及身份、支付、数据迁移或公开接口，仍应提高审查和验证强度。模型能力不能替代风险控制。</p><h3 id="_1-3-工具与环境可能比模型更关键" tabindex="-1">1.3 工具与环境可能比模型更关键 <a class="header-anchor" href="#_1-3-工具与环境可能比模型更关键" aria-label="Permalink to &quot;1.3 工具与环境可能比模型更关键&quot;">​</a></h3><p>模型若无法读取真实日志、运行测试或访问必要文档，再强也只能根据残缺信息猜测。相反，能力适中的模型在清晰范围、完整工具和快速反馈下，往往更稳定。</p><h3 id="_1-4-用小型基准验证选择" tabindex="-1">1.4 用小型基准验证选择 <a class="header-anchor" href="#_1-4-用小型基准验证选择" aria-label="Permalink to &quot;1.4 用小型基准验证选择&quot;">​</a></h3><p>可以从团队真实任务中挑选若干代表样本，比较完成率、修改范围、验证通过率、人工修正次数和总耗时。选择应建立在工作负载证据上，而不是只看榜单或单次惊艳演示。</p><p><img src="'+i+'" alt="图 1：任务复杂度、风险与模型能力的选择矩阵"></p><h2 id="二、速度问题先看端到端链路" tabindex="-1">二、速度问题先看端到端链路 <a class="header-anchor" href="#二、速度问题先看端到端链路" aria-label="Permalink to &quot;二、速度问题先看端到端链路&quot;">​</a></h2><h3 id="_2-1-总耗时不只来自生成文本" tabindex="-1">2.1 总耗时不只来自生成文本 <a class="header-anchor" href="#_2-1-总耗时不只来自生成文本" aria-label="Permalink to &quot;2.1 总耗时不只来自生成文本&quot;">​</a></h3><p>读取仓库、搜索文件、安装依赖、编译、运行测试、等待网络和人工审查都计入交付时间。只盯着模型每秒输出多少字，可能优化了最不重要的一段。</p><h3 id="_2-2-缩小范围是最便宜的加速" tabindex="-1">2.2 缩小范围是最便宜的加速 <a class="header-anchor" href="#_2-2-缩小范围是最便宜的加速" aria-label="Permalink to &quot;2.2 缩小范围是最便宜的加速&quot;">​</a></h3><p>明确相关目录、入口、错误日志和验证命令，可以减少代理无目的搜索。任务边界越清楚，工具调用和无关上下文越少。</p><h3 id="_2-3-给代理快速反馈回路" tabindex="-1">2.3 给代理快速反馈回路 <a class="header-anchor" href="#_2-3-给代理快速反馈回路" aria-label="Permalink to &quot;2.3 给代理快速反馈回路&quot;">​</a></h3><p>优先运行最相关的单元测试或静态检查，确认局部修改后再扩大验证范围。每次都从完整构建开始，会让代理在简单错误上等待太久；只跑局部测试而永不全量验证，又会漏掉集成风险。</p><h3 id="_2-4-缓存与可重建环境同样重要" tabindex="-1">2.4 缓存与可重建环境同样重要 <a class="header-anchor" href="#_2-4-缓存与可重建环境同样重要" aria-label="Permalink to &quot;2.4 缓存与可重建环境同样重要&quot;">​</a></h3><p>复用依赖缓存、构建产物和稳定开发环境可以减少机械等待，但缓存必须有明确失效条件。无法解释来源的旧产物，会制造“本地通过、干净环境失败”的假象。</p><p><img src="'+l+'" alt="图 2：AI 编程端到端耗时的组成与优化点"></p><h2 id="三、上下文管理决定长任务是否失真" tabindex="-1">三、上下文管理决定长任务是否失真 <a class="header-anchor" href="#三、上下文管理决定长任务是否失真" aria-label="Permalink to &quot;三、上下文管理决定长任务是否失真&quot;">​</a></h2><h3 id="_3-1-上下文不是越大越好" tabindex="-1">3.1 上下文不是越大越好 <a class="header-anchor" href="#_3-1-上下文不是越大越好" aria-label="Permalink to &quot;3.1 上下文不是越大越好&quot;">​</a></h3><p>会话历史、日志、文件内容和工具结果都占据注意力。无关内容越多，真正关键的约束越容易被淹没。长上下文提供容量，不代表所有内容都应该装进去。</p><h3 id="_3-2-用文件和记录承载稳定事实" tabindex="-1">3.2 用文件和记录承载稳定事实 <a class="header-anchor" href="#_3-2-用文件和记录承载稳定事实" aria-label="Permalink to &quot;3.2 用文件和记录承载稳定事实&quot;">​</a></h3><p>项目规则写入 <code>AGENTS.md</code>，进度写入 <code>ROADMAP.md</code>，架构决策写入专门文档，测试结果保留为文件或日志。稳定事实不必依赖模型记住整段对话。</p><h3 id="_3-3-在自然阶段边界压缩" tabindex="-1">3.3 在自然阶段边界压缩 <a class="header-anchor" href="#_3-3-在自然阶段边界压缩" aria-label="Permalink to &quot;3.3 在自然阶段边界压缩&quot;">​</a></h3><p>完成调查、方案或一个实现阶段后，可以保留目标、决策、改动文件、验证证据和待办，压缩冗长探索过程。压缩的目标是提高信噪比，而不是抹掉关键依据。</p><h3 id="_3-4-一个线程只处理一个主任务" tabindex="-1">3.4 一个线程只处理一个主任务 <a class="header-anchor" href="#_3-4-一个线程只处理一个主任务" aria-label="Permalink to &quot;3.4 一个线程只处理一个主任务&quot;">​</a></h3><p>将无关问题不断追加到同一线程，会让权限、范围和完成条件相互污染。新目标若能独立验收，就应进入新线程或新工作树。</p><p><img src="'+d+'" alt="图 3：上下文从原始材料到高信噪摘要的压缩"></p><h2 id="四、从其他编码代理迁移要迁移工作流" tabindex="-1">四、从其他编码代理迁移要迁移工作流 <a class="header-anchor" href="#四、从其他编码代理迁移要迁移工作流" aria-label="Permalink to &quot;四、从其他编码代理迁移要迁移工作流&quot;">​</a></h2><h3 id="_4-1-不要逐个翻译命令名称" tabindex="-1">4.1 不要逐个翻译命令名称 <a class="header-anchor" href="#_4-1-不要逐个翻译命令名称" aria-label="Permalink to &quot;4.1 不要逐个翻译命令名称&quot;">​</a></h3><p>不同工具在会话、权限、规则、插件和自动化上的概念并不完全一一对应。只寻找“某命令在 Codex 里叫什么”，容易保留旧工具的使用习惯，却错过新系统的原生边界。</p><h3 id="_4-2-先列出真正依赖的能力" tabindex="-1">4.2 先列出真正依赖的能力 <a class="header-anchor" href="#_4-2-先列出真正依赖的能力" aria-label="Permalink to &quot;4.2 先列出真正依赖的能力&quot;">​</a></h3><p>盘点现有工作流：项目规则放在哪里，常用自动化如何触发，外部工具怎样连接，权限怎样批准，任务怎样验证和发布。然后再为每项能力选择 Codex 中合适的配置、Skill、MCP 或脚本。</p><h3 id="_4-3-用一个真实项目做双轨验证" tabindex="-1">4.3 用一个真实项目做双轨验证 <a class="header-anchor" href="#_4-3-用一个真实项目做双轨验证" aria-label="Permalink to &quot;4.3 用一个真实项目做双轨验证&quot;">​</a></h3><p>选择规模适中、测试完备的项目，让旧流程和新流程完成同一组任务。比较结果质量、耗时、人工干预和安全边界，逐步迁移，而不是一次性替换全部团队工具。</p><h3 id="_4-4-清理重复事实源" tabindex="-1">4.4 清理重复事实源 <a class="header-anchor" href="#_4-4-清理重复事实源" aria-label="Permalink to &quot;4.4 清理重复事实源&quot;">​</a></h3><p>迁移期间最危险的是两套规则长期并存。确认新流程稳定后，应明确哪个文件是当前事实源，旧配置是归档还是废弃，避免代理读取相互冲突的指令。</p><p><img src="'+n+'" alt="图 4：从旧代理工作流映射到 Codex 能力层"></p><h2 id="五、一个可复用的决策框架" tabindex="-1">五、一个可复用的决策框架 <a class="header-anchor" href="#五、一个可复用的决策框架" aria-label="Permalink to &quot;五、一个可复用的决策框架&quot;">​</a></h2><p>当任务不理想时，依次检查：目标是否可验证，范围是否过大，上下文是否混杂，工具是否拿到真实证据，环境是否可重建，权限是否阻塞必要动作，验证是否快速可靠。只有这些条件基本成立，再评估模型是否需要更强推理或不同速度档位。</p><p>这套顺序能避免把工程系统问题误判成模型问题。换模型可能暂时改善结果，却不会修复缺失测试、错误目录、失效缓存或冲突规则。</p><h2 id="六、把速度定义为-更快得到可信结果" tabindex="-1">六、把速度定义为“更快得到可信结果” <a class="header-anchor" href="#六、把速度定义为-更快得到可信结果" aria-label="Permalink to &quot;六、把速度定义为“更快得到可信结果”&quot;">​</a></h2><p>AI 编程的速度不应只统计首次补丁生成时间，而要统计从需求提出到证据齐全、可安全合并的总时间。一个慢几分钟但范围准确、测试可靠的结果，通常比瞬间生成却需要数小时人工排错更快。</p><p>模型选型、上下文压缩、环境治理和分段交付最终服务于同一目标：减少返工，让每一轮计算更接近可接受结果。</p><h2 id="七、参考资料" tabindex="-1">七、参考资料 <a class="header-anchor" href="#七、参考资料" aria-label="Permalink to &quot;七、参考资料&quot;">​</a></h2><p><a href="https://coding.stormzhang.ai/codex/30-models" target="_blank" rel="noreferrer">Codex 系列第 30 篇：模型选择</a></p><p><a href="https://coding.stormzhang.ai/codex/31-speed" target="_blank" rel="noreferrer">Codex 系列第 31 篇：速度与上下文</a></p><p><a href="https://coding.stormzhang.ai/codex/32-migrate-from-claude-code" target="_blank" rel="noreferrer">Codex 系列第 32 篇：迁移</a></p><p><a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">OpenAI Models 官方文档</a></p><p><a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">OpenAI Best practices 官方文档</a></p><p><a href="https://learn.chatgpt.com/docs/import" target="_blank" rel="noreferrer">OpenAI Import 官方文档</a></p>',56)])])}const q=a(c,[["render",h]]);export{b as __pageData,q as default};
